        log("=== WALA Analysis of Closure Compiler ===");
        log("Application JAR: " + appJar);
        log("Output Directory: " + outputDir);
        log("");

        long totalStart = System.currentTimeMillis();

        // Step 1: Create analysis scope
        logSection("1. Creating Analysis Scope");
        long start = System.currentTimeMillis();
        File exclusionsFile = null;
        // Use makeJavaBinaryAnalysisScope which takes a JAR file directly
        AnalysisScope scope =
                AnalysisScopeReader.instance.makeJavaBinaryAnalysisScope(
                        appJar, exclusionsFile);
        long elapsed = System.currentTimeMillis() - start;
        log("Analysis scope created in " + elapsed + "ms");
        log("");

        // Step 2: Build class hierarchy
        logSection("2. Building Class Hierarchy");
        start = System.currentTimeMillis();
        IClassHierarchy cha = ClassHierarchyFactory.make(scope);
        elapsed = System.currentTimeMillis() - start;
        log("Class hierarchy built in " + elapsed + "ms");
        int numClasses = cha.getNumberOfClasses();
        log("Total number of classes: " + numClasses);

        // Count classes by class loader
        int appClasses = 0, extClasses = 0, primClasses = 0;
        for (IClass klass : cha) {
            ClassLoaderReference clr = klass.getClassLoader().getReference();
            if (clr.equals(ClassLoaderReference.Application)) {
                appClasses++;
            } else if (clr.equals(ClassLoaderReference.Extension)) {
                extClasses++;
            } else if (clr.equals(ClassLoaderReference.Primordial)) {
                primClasses++;
            }
        }
        log("  Application classes: " + appClasses);
        log("  Extension classes: " + extClasses);
        log("  Primordial classes: " + primClasses);
        log("");

        // Step 3: Analyze class hierarchy - list all application classes
        logSection("3. Application Classes in Class Hierarchy");
        List<IClass> appClassList = new ArrayList<>();
        for (IClass klass : cha) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                appClassList.add(klass);
            }
        }
        appClassList.sort(Comparator.comparing(c -> c.getName().toString()));
        log("Application classes (" + appClassList.size() + " total):");
        for (IClass klass : appClassList) {
            int numMethods = klass.getDeclaredMethods().size();
            log("  " + klass.getName().toString() + " (" + numMethods + " methods)");
        }
        log("");

