        logSection("4. Method Statistics");
        int totalMethods = 0;
        int appMethods = 0;
        int staticMethods = 0;
        int privateMethods = 0;
        int publicMethods = 0;
        int protectedMethods = 0;
        Set<IClass> classWithMostMethods = new HashSet<>();
        int maxMethods = 0;
        IClass largestClass = null;

        for (IClass klass : cha) {
            int classMethodCount = klass.getDeclaredMethods().size();
            totalMethods += classMethodCount;
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                appMethods += classMethodCount;
            }
            if (classMethodCount > maxMethods) {
                maxMethods = classMethodCount;
                largestClass = klass;
            }
            for (IMethod method : klass.getDeclaredMethods()) {
                if (method.isStatic()) staticMethods++;
                if (method.isPrivate()) privateMethods++;
                else if (method.isPublic()) publicMethods++;
                else if (method.isProtected()) protectedMethods++;
            }
        }
        log("Total methods in hierarchy: " + totalMethods);
        log("  Application methods: " + appMethods);
        log("  Static methods: " + staticMethods);
        log("  Private methods: " + privateMethods);
        log("  Public methods: " + publicMethods);
        log("  Protected methods: " + protectedMethods);
        if (largestClass != null) {
            log("Largest class by method count: " + largestClass.getName() + " (" + maxMethods + " methods)");
        }
        log("");

