        logSection("5. Building Call Graph (0-CFA)");
        start = System.currentTimeMillis();
        AnalysisOptions options = new AnalysisOptions(scope, Util.makeMainEntrypoints(cha, "com.google.javascript.jscomp.CommandLineRunner"));
        options.setReflectionOptions(ReflectionOptions.NONE);
        IAnalysisCacheView cache = new AnalysisCacheImpl();
        CallGraphBuilder<InstanceKey> builder = Util.makeZeroCFABuilder(options, cache, cha);

        log("Building call graph...");
        CallGraph cg = builder.makeCallGraph(options, null);
        elapsed = System.currentTimeMillis() - start;
        log("Call graph built in " + elapsed + "ms");
        log("");

        // Step 6: Call graph statistics
        logSection("6. Call Graph Statistics");
        String stats = CallGraphStats.getStats(cg);
        log(stats);
        log("");

