        logSection("7. Entrypoints");
        Iterable<Entrypoint> entrypoints = Util.makeMainEntrypoints(cha, "com.google.javascript.jscomp.CommandLineRunner");
        int entryCount = 0;
        for (Entrypoint ep : entrypoints) {
            log("  Entry: " + ep.getMethod().getSignature());
            entryCount++;
        }
        log("Total entrypoints: " + entryCount);
        log("");

        // Step 8: List application call graph nodes
        logSection("8. Application Call Graph Nodes (Sample)");
        int appNodeCount = 0;
        int totalNodeCount = 0;
        List<String> appNodeNames = new ArrayList<>();
        for (CGNode node : cg) {
            totalNodeCount++;
            if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) {
                appNodeCount++;
                if (appNodeNames.size() < 200) {
                    appNodeNames.add(node.getMethod().getSignature());
                }
            }
        }
