        log("First 200 application nodes:");
        Collections.sort(appNodeNames);
        for (String name : appNodeNames) {
            log("  " + name);
        }
        log("");

        // Step 9: Find highly connected nodes (most callees)
        logSection("9. Most Connected Call Graph Nodes (by outgoing edges)");
        List<CGNode> nodesByOutDegree = new ArrayList<>();
        for (CGNode node : cg) {
            if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) {
                nodesByOutDegree.add(node);
            }
        }
        nodesByOutDegree.sort((a, b) -> cg.getSuccNodeCount(b) - cg.getSuccNodeCount(a));
        int limit = Math.min(50, nodesByOutDegree.size());
        for (int i = 0; i < limit; i++) {
            CGNode node = nodesByOutDegree.get(i);
            log("  " + node.getMethod().getSignature() + " -> " + cg.getSuccNodeCount(node) + " callees");
        }
        log("");

        // Step 10: Find most called methods (by incoming edges)
        logSection("10. Most Called Methods (by incoming edges)");
        List<CGNode> nodesByInDegree = new ArrayList<>();
        for (CGNode node : cg) {
            if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) {
                nodesByInDegree.add(node);
            }
        }
        // Count incoming edges
