        nodesByInDegree.sort((a, b) -> cg.getPredNodeCount(b) - cg.getPredNodeCount(a));
        limit = Math.min(50, nodesByInDegree.size());
        for (int i = 0; i < limit; i++) {
            CGNode node = nodesByInDegree.get(i);
            log("  " + node.getMethod().getSignature() + " <- " + cg.getPredNodeCount(node) + " callers");
        }
        log("");

        // Step 11: Build IRs for all application methods
        logSection("11. IR Construction for Application Methods");
        start = System.currentTimeMillis();
        int irCount = 0;
        int irErrorCount = 0;
        int totalInstructions = 0;
        IAnalysisCacheView irCache = new AnalysisCacheImpl();
        for (IClass klass : cha) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                for (IMethod method : klass.getDeclaredMethods()) {
                    try {
                        com.ibm.wala.classLoader.IR ir = irCache.getIR(method, com.ibm.wala.ipa.callgraph.impl.Everywhere.EVERYWHERE);
                        if (ir != null) {
                            irCount++;
                            totalInstructions += ir.getInstructions().length;
                        }
                    } catch (Exception e) {
                        irErrorCount++;
                    }
                }
            }
        }
        elapsed = System.currentTimeMillis() - start;
        log("IRs constructed for " + irCount + " methods in " + elapsed + "ms");
