            if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) {
                nodesByOutDegree.add(node);
            }
        }
        nodesByOutDegree.sort((a, b) -> cg.getSuccNodeCount(b) - cg.getSuccNodeCount(a));
        int limit = Math.min(50, nodesByOutDegree.size());
        for (int i = 0; i < limit; i++) {
            CGNode node = nodesByOutDegree.get(i);
            log("  " + node.getMethod().getSignature() + " -> " + cg.getSuccNodeCount(node) + " callees");
        }
        log("");

        // Step 10: Most called methods (incoming edges)
        logSection("10. Most Called Methods (by incoming edges)");
        List<CGNode> nodesByInDegree = new ArrayList<>();
        for (CGNode node : cg) {
            if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) {
                nodesByInDegree.add(node);
            }
        }
        nodesByInDegree.sort((a, b) -> cg.getPredNodeCount(b) - cg.getPredNodeCount(a));
        limit = Math.min(50, nodesByInDegree.size());
        for (int i = 0; i < limit; i++) {
            CGNode node = nodesByInDegree.get(i);
            log("  " + node.getMethod().getSignature() + " <- " + cg.getPredNodeCount(node) + " callers");
        }
        log("");

        // Step 11: IR construction
        logSection("11. IR Construction for Application Methods");
        start = System.currentTimeMillis();
        int irCount = 0;
        int irErrorCount = 0;
        int totalInstructions = 0;
        IAnalysisCacheView irCache = new AnalysisCacheImpl();
        for (IClass klass : cha) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                for (IMethod method : klass.getDeclaredMethods()) {
                    try {
                        IR ir = irCache.getIR(method, Everywhere.EVERYWHERE);
                        if (ir != null) {
                            irCount++;
                            SSAInstruction[] instrs = ir.getInstructions();
                            if (instrs != null) {
                                totalInstructions += instrs.length;
                            }
                        }
                    } catch (Exception e) {
                        irErrorCount++;
                    }
                }
            }
        }
        elapsed = System.currentTimeMillis() - start;
        log("IRs constructed for " + irCount + " methods in " + elapsed + "ms");
        log("IR construction errors: " + irErrorCount);
        log("Total instructions across all IRs: " + totalInstructions);
        if (irCount > 0) {
            log("Average instructions per method: " + (totalInstructions / irCount));
        }
        log("");

        // Step 12: Package-level analysis
        logSection("12. Package-Level Analysis");
        Map<String, Integer> packageClassCount = new TreeMap<>();
        Map<String, Integer> packageMethodCount = new TreeMap<>();
        for (IClass klass : cha) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                String className = klass.getName().toString();
                String packageName;
                int lastSlash = className.lastIndexOf('/');
                if (lastSlash > 0) {
                    packageName = className.substring(0, lastSlash).replace('/', '.');
                } else {
                    packageName = "(default)";
                }
                packageClassCount.merge(packageName, 1, Integer::sum);
                packageMethodCount.merge(packageName, klass.getDeclaredMethods().size(), Integer::sum);
            }
        }
        log("Packages with class counts:");
        for (Map.Entry<String, Integer> entry : packageClassCount.entrySet()) {
            log("  " + entry.getKey() + ": " + entry.getValue() + " classes, " +
                packageMethodCount.getOrDefault(entry.getKey(), 0) + " methods");
        }
        log("");

        // Write summary
        long totalElapsed = System.currentTimeMillis() - totalStart;
        logSection("=== ANALYSIS COMPLETE ===");
        log("Total analysis time: " + totalElapsed + "ms (" + (totalElapsed / 1000.0) + "s)");

        summary.println("=== WALA Analysis of Google Closure Compiler ===");
        summary.println("Analysis Tool: WALA (Watson Libraries for Analysis)");
        summary.println("Version: 1.8.1-SNAPSHOT (built from source)");
        summary.println("Target: closure-compiler (Google Closure Compiler)");
        summary.println("JAR analyzed: " + appJar);
        summary.println();
        summary.println("=== Results Summary ===");
        summary.println("1. Class Hierarchy:");
        summary.println("   Total classes: " + numClasses);
        summary.println("   Application classes: " + appClasses);
        summary.println("   Primordial classes: " + primClasses);
        summary.println();
        summary.println("2. Method Statistics:");
        summary.println("   Total methods: " + totalMethods);
        summary.println("   Application methods: " + appMethods);
        summary.println("   Static methods: " + staticMethods);
        summary.println("   Private methods: " + privateMethods);
        summary.println("   Public methods: " + publicMethods);
        summary.println();
        summary.println("3. Call Graph (0-CFA):");
        summary.println("   Nodes: " + cgNodes);
        summary.println("   Edges: " + cgEdges);
        summary.println("   Application nodes: " + appNodeCount);
        summary.println();
        summary.println("4. IR Construction:");
        summary.println("   IRs constructed: " + irCount);
        summary.println("   Total instructions: " + totalInstructions);
        summary.println("   IR errors: " + irErrorCount);
        summary.println();
        summary.println("5. Packages:");
        summary.println("   Total packages: " + packageClassCount.size());
        summary.println();
        summary.println("6. Timing:");
        summary.println("   Total analysis time: " + totalElapsed + "ms (" + (totalElapsed / 1000.0) + "s)");
        summary.println();
        summary.println("Output files:");
        summary.println("  wala-analysis-summary.txt - This summary");
        summary.println("  wala-analysis-details.txt - Detailed analysis output");
        summary.println("  wala-callgraph-edges.txt - Call graph edges (application nodes)");

        // Write call graph edges
        PrintWriter cgOut = new PrintWriter(new FileWriter(new File(outDir, "wala-callgraph-edges.txt")));
        cgOut.println("=== Call Graph Edges (Application -> Application) ===");
        int edgeCount = 0;
        for (CGNode src : cg) {
            if (!src.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) continue;
            for (CGNode dst : cg) {
                if (cg.hasEdge(src, dst)) {
                    if (dst.getMethod().getDeclaringClass().getClassLoader().getReference()
                            .equals(ClassLoaderReference.Application)) {
                        cgOut.println(src.getMethod().getSignature() + " -> " + dst.getMethod().getSignature());
                        edgeCount++;
                    }
                }
            }
        }
        cgOut.println("--- Total app->app edges: " + edgeCount + " ---");
        cgOut.close();

        out.close();
        summary.close();

        System.out.println("Analysis complete. Results saved to " + outputDir);
    }

    static void log(String msg) {
        out.println(msg);
        out.flush();
        System.out.println(msg);
    }

    static void logSection(String title) {
        String line = "========================================";
        out.println();
        out.println(line);
        out.println(title);
        out.println(line);
        out.flush();
        System.out.println();
        System.out.println(line);
        System.out.println(title);
        System.out.println(line);
    }
}
