import com.ibm.wala.ipa.callgraph.CallGraph;
import com.ibm.wala.ipa.callgraph.CGNode;
import com.ibm.wala.types.ClassLoaderReference;
import com.ibm.wala.util.config.AnalysisScopeReader;

import java.io.File;
import java.io.FileWriter;
import java.io.PrintWriter;
import java.util.Iterator;

/**
 * Standalone script to extract call graph edges efficiently.
 * Uses the graph's successor iterator instead of all-pairs checking.
 */
public class WriteCallGraphEdges {
    public static void main(String[] args) throws Exception {
        String appJar = args[0];
        String outputFile = args[1];

        // Build scope and class hierarchy
        com.ibm.wala.ipa.callgraph.AnalysisScope scope =
                AnalysisScopeReader.instance.makeJavaBinaryAnalysisScope(appJar, null);
        com.ibm.wala.ipa.cha.IClassHierarchy cha =
                com.ibm.wala.ipa.cha.ClassHierarchyFactory.make(scope);

        // Build call graph
        com.ibm.wala.ipa.callgraph.AnalysisOptions options =
                new com.ibm.wala.ipa.callgraph.AnalysisOptions(
                        scope, com.ibm.wala.ipa.callgraph.impl.Util.makeMainEntrypoints(cha));
        options.setReflectionOptions(
                com.ibm.wala.ipa.callgraph.AnalysisOptions.ReflectionOptions.NONE);
        com.ibm.wala.ipa.callgraph.IAnalysisCacheView cache =
                new com.ibm.wala.ipa.callgraph.AnalysisCacheImpl();
        com.ibm.wala.ipa.callgraph.CallGraphBuilder<com.ibm.wala.ipa.callgraph.propagation.InstanceKey> builder =
                com.ibm.wala.ipa.callgraph.impl.Util.makeZeroCFABuilder(
                        com.ibm.wala.classLoader.JavaLanguage.get(), options, cache, cha, scope);

        System.out.println("Building call graph...");
        CallGraph cg = builder.makeCallGraph(options, null);
        System.out.println("Call graph built: " + cg.getNumberOfNodes() + " nodes");

        // Write edges efficiently using succNode iterator
        PrintWriter pw = new PrintWriter(new FileWriter(outputFile));
        pw.println("=== Call Graph Edges (Application -> Application) ===");
        int edgeCount = 0;

        for (CGNode src : cg) {
            if (!src.getMethod().getDeclaringClass().getClassLoader().getReference()
                    .equals(ClassLoaderReference.Application)) continue;

            // Use the succNode iterator which is O(edges) not O(nodes)
            Iterator<CGNode> succIter = cg.getSuccNodes(src);
            while (succIter.hasNext()) {
                CGNode dst = succIter.next();
                if (dst.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    pw.println(src.getMethod().getSignature() + " -> " + dst.getMethod().getSignature());
                    edgeCount++;
                }
            }
        }

        pw.println("--- Total app->app edges: " + edgeCount + " ---");
        pw.close();
        System.out.println("Wrote " + edgeCount + " edges to " + outputFile);
    }
}
